func (this *CTabFolder) RemoveTabControlControlUpdate(controlLike ControlLike, update bool) {
	var control *Control
	if controlLike != nil {
		control = controlLike.AsControl()
	}
	_ = control
	if control != (nil) && control.GetParent() != upcastCTabFolderToComposite(this) {
		Error(ERROR_INVALID_ARGUMENT)
	}
	var index int32 = -1
	for i := int32(0); i < int32(len(this.controls)); i++ {
		if this.controls[i] == control {
			index = i
			break
		}
	}
	if index == -1 {
		return
	}
	if !control.IsDisposed() {
		control.RemoveListener(Resize, this.listener)
		control.RemoveListener(ZoomChanged, this.tabControlZoomListener)
		control.impl.setBackgroundWithColor_(nil)
		control.impl.setBackgroundImage_(nil)
		_, ok734 := isControlToComposite(control)
		if ok734 {
			(castControlToComposite(control)).SetBackgroundMode(INHERIT_NONE)
		}
	}
	if this.controlBkImages[index] != (nil) && !this.controlBkImages[index].impl.isDisposed_() {
		this.controlBkImages[index].impl.dispose_()
	}
	if int32(len(this.controls)) == 1 {
		this.controls = make([]*Control, 0)
		this.controlAlignments = make([]int32, 0)
		this.controlRects = make([]*Rectangle, 0)
		this.controlBkImages = make([]*Image, 0)
	} else {
		var newControls []*Control = make([]*Control, int32(len(this.controls))-1)
		copy(newControls[0:], this.controls[0:0+index])
		copy(newControls[index:], this.controls[index+1:index+1+int32(len(this.controls))-index-1])
		this.controls = newControls
		var newAlignments []int32 = make([]int32, int32(len(this.controls)))
		copy(newAlignments[0:], this.controlAlignments[0:0+index])
		copy(newAlignments[index:], this.controlAlignments[index+1:index+1+int32(len(this.controls))-index])
		this.controlAlignments = newAlignments
		var newRects []*Rectangle = make([]*Rectangle, int32(len(this.controls)))
		copy(newRects[0:], this.controlRects[0:0+index])
		copy(newRects[index:], this.controlRects[index+1:index+1+int32(len(this.controls))-index])
		this.controlRects = newRects
		var newBkImages []*Image = make([]*Image, int32(len(this.controls)))
		copy(newBkImages[0:], this.controlBkImages[0:0+index])
		copy(newBkImages[index:], this.controlBkImages[index+1:index+1+int32(len(this.controls))-index])
		this.controlBkImages = newBkImages
	}
	if update {
		this.UpdateFolder(CTabFolderUPDATE_TAB_HEIGHT | CTabFolderREDRAW)
	}
}
